namespace EquipmentMonitoring.Application.DTOs;

/// <summary>Describes equipment returned after registration.</summary>
public class EquipmentResponseDto
{
    /// <summary>Gets or sets the unique identifier generated by the server.</summary>
    public Guid Id { get; set; }

    /// <summary>Gets or sets the equipment name.</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>Gets or sets the equipment type.</summary>
    public string Type { get; set; } = string.Empty;

    /// <summary>Gets or sets the unique equipment serial number.</summary>
    public string SerialNumber { get; set; } = string.Empty;

    /// <summary>Gets or sets the equipment location.</summary>
    public string Location { get; set; } = string.Empty;

    /// <summary>Gets or sets the initial equipment status assigned by the domain model.</summary>
    public string Status { get; set; } = string.Empty;

    /// <summary>Gets or sets the UTC date and time when the equipment was created.</summary>
    public DateTime CreatedAt { get; set; }
}
